114	        ...scanText(String(xmp), {
115	          record: ctx.record,
116	          artifactPath: ctx.bodyPath,
117	          extractor: 'pdf',
118	          method: 'PDF XMP metadata',
119	        }),
120	      );
121	    }
122	
123	    const attachments: unknown = await doc.getAttachments().catch(() => null);
124	    if (attachments && typeof attachments === 'object') {
125	      for (const [name, value] of Object.entries(attachments as Record<string, unknown>)) {
126	        const content = (value as { content?: Uint8Array }).content;
127	        if (!content) continue;
128	        hits.push(
129	          ...scanText(Buffer.from(content).toString('utf8'), {
130	            record: ctx.record,
131	            artifactPath: ctx.bodyPath,
132	            extractor: 'pdf',
133	            method: `PDF embedded file "${name}"`,
134	          }),
135	        );
136	      }
137	    }
138	
139	    for (let pageNumber = 1; pageNumber <= doc.numPages; pageNumber += 1) {
140	      const page = await doc.getPage(pageNumber);
141	      const content = await page.getTextContent();
142	      const text = content.items
143	        .map((item: unknown) =>
144	          typeof (item as PdfTextItem).str === 'string' ? (item as PdfTextItem).str : '',
145	        )
146	        .join(' ');
147	      hits.push(
148	        ...scanText(String(text), {
149	          record: ctx.record,
150	          artifactPath: ctx.bodyPath,
151	          extractor: 'pdf',
152	          method: `PDF page ${pageNumber} text layer`,
153	        }),
154	      );
155	      const annotations: unknown[] = await page.getAnnotations().catch(() => []);
156	      if (annotations.length > 0) {
157	        hits.push(
158	          ...scanText(JSON.stringify(annotations), {
159	            record: ctx.record,
160	            artifactPath: ctx.bodyPath,
161	            extractor: 'pdf',
162	            method: `PDF page ${pageNumber} annotations`,
163	          }),
164	        );
165	      }
166	    }
167	  } finally {
168	    await doc.destroy().catch(() => undefined);
169	  }
170	  return hits;
171	}
172	
173	/** Inflate every `stream ... endstream` payload that happens to be zlib data. */
174	export function inflateStreams(body: Buffer): string[] {
175	  const out: string[] = [];
176	  const marker = Buffer.from('stream', 'latin1');
177	  const endMarker = Buffer.from('endstream', 'latin1');
178	  let index = body.indexOf(marker);
179	  while (index !== -1) {
180	    let start = index + marker.length;
181	    if (body[start] === 0x0d) start += 1;
182	    if (body[start] === 0x0a) start += 1;
183	    const end = body.indexOf(endMarker, start);
184	    if (end === -1) break;
185	    const slice = body.subarray(start, end);
186	    try {
187	      out.push(inflateSync(slice).toString('latin1'));
188	    } catch {
189	      /* not a Flate stream (or corrupt); the raw-text extractor still sees it */
190	    }
191	    index = body.indexOf(marker, end + endMarker.length);
192	  }
193	  return out;
194	}
195	
196	/** Pull the string arguments out of Tj / TJ / ' / " text-showing operators. */
197	export function decodePdfTextOperators(content: string): string {
198	  const pieces: string[] = [];
199	  for (const match of content.matchAll(/\(((?:\\.|[^\\()])*)\)\s*(?:Tj|TJ|'|")/g)) {
200	    pieces.push(unescapePdfString(match[1] ?? ''));
201	  }
202	  for (const match of content.matchAll(/\[((?:[^\][]|\\.)*)\]\s*TJ/g)) {
203	    const inner = match[1] ?? '';
204	    for (const part of inner.matchAll(/\(((?:\\.|[^\\()])*)\)/g)) {
205	      pieces.push(unescapePdfString(part[1] ?? ''));
206	    }
207	    // Kerned arrays split words across elements; join with no separator too.
208	    pieces.push(
209	      [...inner.matchAll(/\(((?:\\.|[^\\()])*)\)/g)]
210	        .map((part) => unescapePdfString(part[1] ?? ''))
211	        .join(''),
212	    );
213	  }
214	  return pieces.join('\n');
215	}
216	
217	function unescapePdfString(value: string): string {
218	  return value
219	    .replace(/\\([0-7]{1,3})/g, (_m, oct: string) => String.fromCharCode(parseInt(oct, 8)))
220	    .replace(/\\n/g, '\n')
221	    .replace(/\\r/g, '\r')
222	    .replace(/\\t/g, '\t')
223	    .replace(/\\([()\\])/g, '$1');
224	}

