65	function crc32(buffer: Buffer): number {
66	  let crc = 0xffffffff;
67	  for (const byte of buffer) {
68	    crc ^= byte;
69	    for (let i = 0; i < 8; i += 1) {
70	      crc = crc & 1 ? (crc >>> 1) ^ 0xedb88320 : crc >>> 1;
71	    }
72	  }
73	  return (crc ^ 0xffffffff) >>> 0;
74	}
75	
76	function pngChunk(type: string, data: Buffer): Buffer {
77	  const length = Buffer.alloc(4);
78	  length.writeUInt32BE(data.length, 0);
79	  const typeAndData = Buffer.concat([Buffer.from(type, 'latin1'), data]);
80	  const crc = Buffer.alloc(4);
81	  crc.writeUInt32BE(crc32(typeAndData), 0);
82	  return Buffer.concat([length, typeAndData, crc]);
83	}
