92	/** A structurally valid 1×1 PNG with optional text chunks and appended bytes. */
93	export function buildPng(options: PngOptions = {}): Buffer {
94	  const signature = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
95	  const ihdr = Buffer.alloc(13);
96	  ihdr.writeUInt32BE(1, 0);
97	  ihdr.writeUInt32BE(1, 4);
98	  ihdr[8] = 8; // bit depth
99	  ihdr[9] = 0; // greyscale
100	  const parts = [signature, pngChunk('IHDR', ihdr)];
101	
102	  if (options.tEXt) {
103	    parts.push(
104	      pngChunk(
105	        'tEXt',
106	        Buffer.concat([
107	          Buffer.from(options.tEXt.keyword, 'latin1'),
108	          Buffer.from([0]),
109	          Buffer.from(options.tEXt.value, 'latin1'),
110	        ]),
111	      ),
112	    );
113	  }
114	  if (options.zTXt) {
115	    parts.push(
116	      pngChunk(
117	        'zTXt',
118	        Buffer.concat([
119	          Buffer.from(options.zTXt.keyword, 'latin1'),
120	          Buffer.from([0, 0]),
121	          deflateSync(Buffer.from(options.zTXt.value, 'utf8')),
122	        ]),
123	      ),
124	    );
125	  }
126	  if (options.iTXt) {
127	    parts.push(
128	      pngChunk(
129	        'iTXt',
130	        Buffer.concat([
131	          Buffer.from(options.iTXt.keyword, 'latin1'),
132	          Buffer.from([0, 0, 0]), // compression flag + method
133	          Buffer.from([0]), // empty language tag
134	          Buffer.from([0]), // empty translated keyword
135	          Buffer.from(options.iTXt.value, 'utf8'),
136	        ]),
137	      ),
138	    );
139	  }
140	
141	  parts.push(pngChunk('IDAT', deflateSync(Buffer.from([0, 0]))));
142	  parts.push(pngChunk('IEND', Buffer.alloc(0)));
143	  if (options.trailer) parts.push(Buffer.from(options.trailer, 'utf8'));
144	  return Buffer.concat(parts);
145	}
