149	/** A minimal JPEG carrying a COM marker and an EXIF UserComment. */
150	export function buildJpeg(comment: string, exifComment?: string): Buffer {
151	  const parts: Buffer[] = [Buffer.from([0xff, 0xd8])];
152	
153	  if (exifComment) parts.push(buildExifApp1(exifComment));
154	
155	  const commentBytes = Buffer.from(comment, 'utf8');
156	  const comHeader = Buffer.alloc(4);
157	  comHeader.writeUInt16BE(0xfffe, 0);
158	  comHeader.writeUInt16BE(commentBytes.length + 2, 2);
159	  parts.push(comHeader, commentBytes);
160	
161	  parts.push(Buffer.from([0xff, 0xd9]));
162	  return Buffer.concat(parts);
163	}
164	
165	/**
166	 * APP1/Exif segment with a single UserComment (tag 0x9286) in the Exif IFD,
167	 * encoded the way the target site encodes it: an `UNICODE\0` character-set marker
168	 * followed by UTF-16LE — the case a naive `String(value)` renders as `[object Object]`.
169	 */
170	function buildExifApp1(comment: string): Buffer {
171	  const commentBytes = Buffer.concat([
172	    Buffer.from('UNICODE\0', 'latin1'),
173	    Buffer.from(comment, 'utf16le'),
174	  ]);
175	
176	  // TIFF header (little-endian) + IFD0 with one entry pointing at the Exif IFD.
177	  const tiff: Buffer[] = [];
178	  const header = Buffer.alloc(8);
179	  header.write('II', 0, 'latin1');
180	  header.writeUInt16LE(42, 2);
181	  header.writeUInt32LE(8, 4); // IFD0 offset
182	  tiff.push(header);
183	
184	  const ifd0 = Buffer.alloc(2 + 12 + 4);
185	  ifd0.writeUInt16LE(1, 0); // one entry
186	  ifd0.writeUInt16LE(0x8769, 2); // ExifIFDPointer
187	  ifd0.writeUInt16LE(4, 4); // LONG
188	  ifd0.writeUInt32LE(1, 6);
189	  ifd0.writeUInt32LE(8 + ifd0.length, 10); // offset of the Exif IFD
190	  ifd0.writeUInt32LE(0, 14); // no next IFD
191	  tiff.push(ifd0);
192	
193	  const exifIfd = Buffer.alloc(2 + 12 + 4);
194	  const exifIfdOffset = 8 + ifd0.length;
195	  exifIfd.writeUInt16LE(1, 0);
196	  exifIfd.writeUInt16LE(0x9286, 2); // UserComment
197	  exifIfd.writeUInt16LE(7, 4); // UNDEFINED
198	  exifIfd.writeUInt32LE(commentBytes.length, 6);
199	  exifIfd.writeUInt32LE(exifIfdOffset + exifIfd.length, 10);
200	  exifIfd.writeUInt32LE(0, 14);
201	  tiff.push(exifIfd, commentBytes);
202	
203	  const tiffBuffer = Buffer.concat(tiff);
204	  const payload = Buffer.concat([Buffer.from('Exif\0\0', 'latin1'), tiffBuffer]);
205	  const marker = Buffer.alloc(4);
206	  marker.writeUInt16BE(0xffe1, 0);
207	  marker.writeUInt16BE(payload.length + 2, 2);
208	  return Buffer.concat([marker, payload]);
209	}
