213	export function buildZip(files: Record<string, string | Buffer>): Buffer {
214	  const entries: Record<string, Uint8Array> = {};
215	  for (const [name, content] of Object.entries(files)) {
216	    entries[name] = new Uint8Array(Buffer.isBuffer(content) ? content : Buffer.from(content, 'utf8'));
217	  }
218	  return Buffer.from(zipSync(entries));
219	}
