23	    const text = ctx.body.toString('utf8');
24	    const hits: PasswordHit[] = [];
25	    const seen = new Set<string>();
26	
27	    const tryDecode = (run: string, urlSafe: boolean): void => {
28	      if (seen.has(run)) return;
29	      seen.add(run);
30	      const normalized = urlSafe ? run.replace(/-/g, '+').replace(/_/g, '/') : run;
31	      const decoded = Buffer.from(normalized, 'base64');
32	      if (decoded.length < 8) return;
33	      // Guard against coincidental matches: require the decode to round-trip.
34	      const reencoded = decoded.toString('base64').replace(/=+$/, '');
35	      if (reencoded !== normalized.replace(/=+$/, '')) return;
36	      const method = urlSafe ? 'base64url-decoded run' : 'base64-decoded run';
37	      hits.push(
38	        ...scanText(decoded.toString('utf8'), {
