2	/**
3	 * CLI entry point.
4	 *
5	 *   crawl    phase 1 only — drive the browser and fill the artifact store
6	 *   extract  phase 2 only — run every extractor over the stored artifacts
7	 *   report   re-render the reports from what is already stored
8	 *   run      crawl, then extract, then report (the default)
9	 */
10	import { loadConfig } from './config.js';
11	import { createLogger } from './logging.js';
12	import { ArtifactStore } from './store/artifactStore.js';
13	import { Harvester } from './harvest/harvester.js';
14	import type { HarvestSummary } from './harvest/harvester.js';
15	import { buildRegistry } from './extract/index.js';
16	import { extractAll } from './extract/pipeline.js';
17	import { writeCrawlReport, writePasswordsJson } from './report/reports.js';
18	import { EXAMPLE_PASSWORD } from './util/password.js';
19	
20	const TARGET_PASSWORD_COUNT = 8;
21	
22	type Command = 'crawl' | 'extract' | 'report' | 'run';
23	
24	function parseCommand(argv: readonly string[]): Command {
25	  const raw = argv[2] ?? 'run';
26	  if (raw === 'crawl' || raw === 'extract' || raw === 'report' || raw === 'run') return raw;
27	  throw new Error(`Unknown command "${raw}". Expected: crawl | extract | report | run`);
28	}
29	
30	async function main(): Promise<number> {
31	  const command = parseCommand(process.argv);
32	  const config = loadConfig();
33	  const log = createLogger(config.logLevel, { command });
34	
35	  log.info('starting', {
36	    baseUrl: config.baseUrl,
37	    artifactDir: config.artifactDir,
38	    outDir: config.outDir,
39	    concurrency: config.concurrency,
40	  });
41	
42	  const store = new ArtifactStore(config.artifactDir);
43	  await store.load();
44	
45	  let harvest: HarvestSummary | null = null;
46	  if (command === 'crawl' || command === 'run') {
47	    const harvester = new Harvester(config, store, log);
48	    harvest = await harvester.run([config.baseUrl]);
49	    log.info('harvest complete', {
50	      processed: harvest.visited,
51	      urlsKnown: harvest.frontier.known,
52	      pending: harvest.frontier.pending,
53	      artifacts: store.all.length,
54	      uniqueBodies: store.uniqueBodyCount,
55	      errors: harvest.errors.length,
56	    });
57	    printArtifactInventory(store);
58	  }
59	
60	  if (command === 'crawl') return 0;
61	
62	  const registry = buildRegistry();
63	  const extraction = await extractAll(store, registry, log, {
64	    onNewPassword: (password, hit, total) => {
65	      process.stdout.write(
66	        `[${String(total).padStart(2, ' ')}/${TARGET_PASSWORD_COUNT}] ${password}  ←  ${hit.method}  @ ${hit.sourceUrl}\n`,
67	      );
68	    },
69	  });
70	
71	  const passwords = await writePasswordsJson(config.outDir, config.baseUrl, extraction);
72	  await writeCrawlReport(config.outDir, {
73	    baseUrl: config.baseUrl,
74	    harvest,
75	    extraction,
76	    store,
77	    registry,
78	  });
79	
80	  process.stdout.write('\n');
81	  process.stdout.write(`Unique passwords: ${passwords.count} / ${TARGET_PASSWORD_COUNT}\n`);
82	  process.stdout.write(`(the published example ${EXAMPLE_PASSWORD} is excluded by design)\n`);
83	  process.stdout.write(`Artifacts scanned: ${extraction.artifactsScanned}`);
84	  process.stdout.write(` (${extraction.bodiesScanned} unique bodies)\n`);
85	  process.stdout.write(`Reports written to ${config.outDir}\n`);
86	
87	  if (passwords.count !== TARGET_PASSWORD_COUNT) {
88	    log.warn('password count does not match the target', {
89	      found: passwords.count,
90	      target: TARGET_PASSWORD_COUNT,
91	    });
92	    return passwords.count > 0 ? 2 : 1;
93	  }
94	  return 0;
95	}
