97	function printArtifactInventory(store: ArtifactStore): void {
98	  const byMime = new Map<string, { count: number; bytes: number }>();
99	  for (const record of store.all) {
100	    const entry = byMime.get(record.mimeType) ?? { count: 0, bytes: 0 };
101	    entry.count += 1;
102	    entry.bytes += record.byteLength;
103	    byMime.set(record.mimeType, entry);
104	  }
105	  process.stdout.write('\nArtifact inventory by content-type:\n');
106	  const rows = [...byMime.entries()].sort((a, b) => b[1].count - a[1].count);
107	  const width = Math.max(...rows.map(([mime]) => mime.length), 12);
108	  for (const [mime, entry] of rows) {
109	    process.stdout.write(
110	      `  ${mime.padEnd(width)}  ${String(entry.count).padStart(5)}  ${entry.bytes.toLocaleString('en-US').padStart(12)} bytes\n`,
111	    );
112	  }
113	  process.stdout.write(`  ${'TOTAL'.padEnd(width)}  ${String(store.all.length).padStart(5)}\n\n`);
114	}
115	
116	main()
117	  .then((code) => {
118	    process.exitCode = code;
119	  })
120	  .catch((error: unknown) => {
121	    const message = error instanceof Error ? (error.stack ?? error.message) : String(error);
122	    process.stderr.write(`${message}\n`);
123	    process.exitCode = 1;
124	  });

1	/**
2	 * Audio/video metadata: ID3v2 and ID3v1 frames, MP4/QuickTime `udta`/`ilst` atoms,
3	 * WebM/Matroska tag elements, and WAV LIST/INFO chunks — all parsed inline so the
4	 * pipeline has no external binary dependency.
5	 */
6	import type { Extractor, PasswordHit } from '../../types.js';
7	import { scanText } from '../hit.js';
8	import { printableRuns } from './text.js';
9	
10	const MEDIA_MIME = /^(audio|video)\//;
11	
12	function isMedia(mimeType: string, url: string): boolean {
13	  return MEDIA_MIME.test(mimeType) || /\.(mp3|mp4|m4a|webm|ogg|wav|mov|aac|flac)$/i.test(url);
14	}
15	
16	export const mediaMetadataExtractor: Extractor = {
17	  id: 'media-metadata',
18	  description: 'ID3 tags, MP4 udta/ilst atoms, Matroska tags, WAV LIST/INFO chunks',
19	  appliesTo: (record, body) => body.length > 16 && isMedia(record.mimeType, record.url),
20	  extract: (ctx) => {
21	    const hits: PasswordHit[] = [];
22	
23	    for (const frame of readId3(ctx.body)) {
24	      hits.push(
25	        ...scanText(frame.value, {
26	          record: ctx.record,
27	          artifactPath: ctx.bodyPath,
28	          extractor: 'media-metadata',
29	          method: `ID3 frame "${frame.id}"`,
30	        }),
31	      );
32	    }
33	
34	    for (const atom of readMp4TextAtoms(ctx.body)) {
35	      hits.push(
36	        ...scanText(atom.value, {
37	          record: ctx.record,
38	          artifactPath: ctx.bodyPath,
39	          extractor: 'media-metadata',
40	          method: `MP4 metadata atom "${atom.type}"`,
41	        }),
42	      );
43	    }
44	
45	    // Matroska/WebM tags and WAV INFO chunks are short printable runs near known
46	    // ASCII keys; a targeted printable sweep is both simpler and more robust than a
47	    // partial EBML parser, and is reported honestly as such.
48	    const head = ctx.body.subarray(0, Math.min(ctx.body.length, 1 << 20));
49	    if (/webm|matroska|wav/i.test(ctx.record.mimeType) || /\.(webm|wav)$/i.test(ctx.record.url)) {
50	      hits.push(
51	        ...scanText(printableRuns(head, 8).join('\n'), {
52	          record: ctx.record,
53	          artifactPath: ctx.bodyPath,
54	          extractor: 'media-metadata',
55	          method: 'printable metadata run in container header',
56	        }),
57	      );
58	    }
59	
60	    return hits;
61	  },
62	};
63	
64	export interface Id3Frame {
65	  id: string;
66	  value: string;
67	}
68	
69	/** ID3v2.3/2.4 frames plus the trailing 128-byte ID3v1 tag. */
70	export function readId3(body: Buffer): Id3Frame[] {
71	  const frames: Id3Frame[] = [];
72	
73	  if (body.subarray(0, 3).toString('latin1') === 'ID3' && body.length > 10) {
74	    const size = syncSafe(body, 6);
75	    let offset = 10;
76	    const end = Math.min(10 + size, body.length);
77	    while (offset + 10 <= end) {
78	      const id = body.subarray(offset, offset + 4).toString('latin1');
79	      if (!/^[A-Z0-9]{4}$/.test(id)) break;
80	      const frameSize = body.readUInt32BE(offset + 4);
81	      if (frameSize <= 0 || offset + 10 + frameSize > end) break;
82	      const payload = body.subarray(offset + 10, offset + 10 + frameSize);
83	      frames.push({ id, value: decodeId3Text(payload) });
84	      offset += 10 + frameSize;
85	    }
86	  }
87	
88	  if (body.length >= 128) {
89	    const tail = body.subarray(body.length - 128);
90	    if (tail.subarray(0, 3).toString('latin1') === 'TAG') {
91	      frames.push({ id: 'ID3v1', value: tail.toString('latin1') });
92	    }
93	  }
94	  return frames;
95	}
96	
97	function syncSafe(body: Buffer, offset: number): number {
98	  return (
99	    ((body[offset] ?? 0) << 21) |
100	    ((body[offset + 1] ?? 0) << 14) |
