106	function decodeId3Text(payload: Buffer): string {
107	  const encoding = payload[0] ?? 0;
108	  const data = payload.subarray(1);
109	  switch (encoding) {
110	    case 1:
111	      return data.toString('utf16le');
112	    case 2: {
113	      const swapped = Buffer.from(data);
114	      if (swapped.length % 2 === 0) swapped.swap16();
115	      return swapped.toString('utf16le');
116	    }
117	    case 3:
118	      return data.toString('utf8');
119	    default:
120	      return data.toString('latin1');
121	  }
122	}
