124	export interface Mp4Atom {
125	  type: string;
126	  value: string;
127	}
128	
129	/** Walk ISO-BMFF boxes and return the text payloads of metadata atoms. */
130	export function readMp4TextAtoms(body: Buffer): Mp4Atom[] {
131	  const atoms: Mp4Atom[] = [];
132	  const interesting = new Set([
133	    'udta',
134	    'meta',
135	    'ilst',
136	    'data',
137	    '©nam',
138	    '©cmt',
139	    '©too',
140	    'desc',
141	    'name',
142	  ]);
143	
144	  const walk = (start: number, end: number, depth: number): void => {
145	    if (depth > 6) return;
146	    let offset = start;
147	    while (offset + 8 <= end) {
148	      const size = body.readUInt32BE(offset);
149	      const type = body.subarray(offset + 4, offset + 8).toString('latin1');
150	      if (size < 8 || offset + size > end) break;
151	      const payloadStart = offset + 8;
152	      if (interesting.has(type)) {
153	        const payload = body.subarray(payloadStart, offset + size);
154	        atoms.push({ type, value: payload.toString('utf8').replace(/\0+/g, ' ') });
155	      }
156	      if (['moov', 'udta', 'meta', 'ilst', 'trak', 'mdia', 'minf', 'stbl'].includes(type)) {
157	        // `meta` carries a 4-byte version/flags prefix before its children.
158	        const childStart = type === 'meta' ? payloadStart + 4 : payloadStart;
159	        walk(childStart, offset + size, depth + 1);
160	      }
161	      offset += size;
162	    }
163	  };
164	
165	  if (body.length > 12 && /ftyp|moov|mdat/.test(body.subarray(4, 8).toString('latin1'))) {
166	    walk(0, body.length, 0);
167	  }
168	  return atoms;
169	}

