import { readFileSync, writeFileSync } from 'node:fs';
import { PNG } from 'pngjs';

const SP = process.argv[2]!;
for (const name of ['pattern', 'diagram-1', 'diagram-2', 'chart-overview']) {
  const src = PNG.sync.read(readFileSync(`${SP}/img/${name}.png`));
  const scale = 8;
  const out = new PNG({ width: src.width * scale, height: src.height * scale });
  // Per-channel histogram stretch, then nearest-neighbour upscale.
  const min = [255, 255, 255];
  const max = [0, 0, 0];
  for (let i = 0; i < src.data.length; i += 4)
    for (let c = 0; c < 3; c += 1) {
      const v = src.data[i + c]!;
      if (v < min[c]!) min[c] = v;
      if (v > max[c]!) max[c] = v;
    }
  for (let y = 0; y < out.height; y += 1)
    for (let x = 0; x < out.width; x += 1) {
      const s = (Math.floor(y / scale) * src.width + Math.floor(x / scale)) * 4;
      const d = (y * out.width + x) * 4;
      for (let c = 0; c < 3; c += 1) {
        const span = Math.max(1, max[c]! - min[c]!);
        out.data[d + c] = Math.round(((src.data[s + c]! - min[c]!) / span) * 255);
      }
      out.data[d + 3] = 255;
    }
  writeFileSync(`${SP}/enh/${name}.png`, PNG.sync.write(out));
  console.log(name, 'range', min, max);
}
