1	/**
2	 * Phase 2 — extract.
3	 *
4	 * Every artifact is passed through every applicable extractor. Nothing short-
5	 * circuits: the point of the coverage matrix in the crawl report is that we can
6	 * show which (content-type × extractor) cells actually ran.
7	 */
8	import type { Logger } from '../logging.js';
9	import type { ArtifactStore } from '../store/artifactStore.js';
10	import type { PasswordHit } from '../types.js';
11	import type { ExtractorRegistry } from './registry.js';
12	import { dedupeHits } from './hit.js';
13	
14	export interface CoverageCell {
15	  applied: number;
16	  hits: number;
17	  errors: number;
18	}
19	
20	export interface ExtractionReport {
21	  hits: PasswordHit[];
22	  uniquePasswords: string[];
23	  /** mimeType -> extractorId -> counts. */
24	  coverage: Record<string, Record<string, CoverageCell>>;
25	  artifactsScanned: number;
26	  bodiesScanned: number;
27	  errors: { artifact: string; extractor: string; message: string }[];
28	  extractorsWithNoHits: string[];
29	}
30	
31	export interface ExtractOptions {
32	  /** Called whenever the unique-password count increases. */
33	  onNewPassword?: (password: string, hit: PasswordHit, total: number) => void;
34	}
35	
36	export async function extractAll(
37	  store: ArtifactStore,
38	  registry: ExtractorRegistry,
39	  log: Logger,
40	  options: ExtractOptions = {},
41	): Promise<ExtractionReport> {
42	  await store.load();
43	
44	  const hits: PasswordHit[] = [];
45	  const coverage: Record<string, Record<string, CoverageCell>> = {};
46	  const errors: ExtractionReport['errors'] = [];
47	  const unique = new Set<string>();
48	  const extractorHitCounts = new Map<string, number>();
49	  const scannedBodies = new Set<string>();
50	
51	  // One pass per (url, body) observation so header-channel hits are attributed to
52	  // the URL that served them; bodies are re-read from the content-addressed store.
53	  const records = [...store.all];
54	  let index = 0;
55	  for (const record of records) {
56	    index += 1;
57	    let body: Buffer;
58	    try {
59	      body = await store.readBody(record);
60	    } catch (error) {
61	      errors.push({ artifact: record.bodyPath, extractor: '(read)', message: message(error) });
62	      continue;
63	    }
64	    scannedBodies.add(record.sha256);
65	
66	    const results = await registry.runAll({
67	      record,
68	      body,
69	      bodyPath: store.relativeToCwd(record),
70	    });
71	
72	    const byMime = (coverage[record.mimeType] ??= {});
73	    for (const result of results) {
74	      const cell = (byMime[result.extractor] ??= { applied: 0, hits: 0, errors: 0 });
75	      if (!result.applied) continue;
76	      cell.applied += 1;
77	      cell.hits += result.hits.length;
78	      if (result.error) {
79	        cell.errors += 1;
80	        errors.push({
81	          artifact: record.bodyPath,
82	          extractor: result.extractor,
83	          message: result.error,
84	        });
85	      }
86	      for (const hit of result.hits) {
87	        hits.push(hit);
88	        extractorHitCounts.set(
89	          result.extractor,
90	          (extractorHitCounts.get(result.extractor) ?? 0) + 1,
91	        );
92	        if (!unique.has(hit.password)) {
93	          unique.add(hit.password);
94	          log.info('password found', {
95	            password: hit.password,
96	            total: unique.size,
97	            url: hit.sourceUrl,
98	            extractor: hit.extractor,
99	            method: hit.method,
100	          });
101	          options.onNewPassword?.(hit.password, hit, unique.size);
102	        }
103	      }
104	    }
105	
106	    if (index % 50 === 0) {
107	      log.debug('extraction progress', { scanned: index, of: records.length, unique: unique.size });
108	    }
109	  }
110	
111	  const extractorsWithNoHits = registry.all
112	    .map((extractor) => extractor.id)
113	    .filter((id) => (extractorHitCounts.get(id) ?? 0) === 0);
114	
115	  return {
116	    hits: dedupeHits(hits),
117	    uniquePasswords: [...unique].sort(),
118	    coverage,
119	    artifactsScanned: records.length,
120	    bodiesScanned: scannedBodies.size,
121	    errors,
122	    extractorsWithNoHits,
123	  };
124	}
125	
126	/** Best (most specific) hit per password, for `passwords.json`. */
127	export function bestHitPerPassword(hits: readonly PasswordHit[]): PasswordHit[] {
128	  const best = new Map<string, PasswordHit>();
129	  for (const hit of hits) {
130	    const existing = best.get(hit.password);
131	    if (!existing || specificity(hit) > specificity(existing)) best.set(hit.password, hit);
132	  }
133	  return [...best.values()].sort((a, b) => a.password.localeCompare(b.password));
134	}
135	
136	/**
137	 * Prefer the extractor that explains *how* the password was hidden over the
138	 * catch-all decoders that merely prove it is present in the bytes.
139	 */
140	function specificity(hit: PasswordHit): number {
141	  const rank: Record<string, number> = {
142	    'raw-text': 0,
143	    'binary-strings': 1,
144	    'utf16-text': 1,
145	    hex: 2,
146	    escapes: 2,
147	    base64: 3,
148	    compression: 3,
149	    'data-uri': 3,
150	    json: 4,
151	    html: 5,
152	    css: 5,
153	    javascript: 5,
154	    svg: 5,
155	    sourcemap: 6,
156	    archive: 6,
157	    'response-headers': 6,
158	    'request-headers': 6,
159	    cookies: 6,
160	    pdf: 7,
161	    'media-metadata': 7,
162	    font: 7,
163	    wasm: 7,
164	    'image-metadata': 8,
165	    'image-chunks': 8,
166	    'trailing-bytes': 8,
167	    ocr: 9,
168	  };
169	  return rank[hit.extractor] ?? 5;
170	}
171	
172	function message(error: unknown): string {
173	  return error instanceof Error ? error.message : String(error);
174	}

