1	/**
2	 * Crawler-trap detection.
3	 *
4	 * This site serves `/report/?page=N` for every N up to at least 1,000,000: each
5	 * page is a fresh slice of generated rows that links only to N±1. A frontier that
6	 * follows it never terminates, so "frontier exhausted" would become an unprovable
7	 * claim.
8	 *
9	 * The guard groups URLs into *templates* (path and query shape with numbers
10	 * normalised away) and saturates a template once it has demonstrably stopped
11	 * producing novelty:
12	 *
13	 *  - structural novelty — pages of the template all reduce to the same shape hash
14	 *    (the body with digits and hex runs masked), and
15	 *  - link novelty — the template's pages have stopped linking anywhere outside it.
16	 *
17	 * Both must hold across a sample before a template is closed, and a hard per-
18	 * template cap acts as a backstop for shapes the heuristic does not model. Every
19	 * decision is recorded so the crawl report can state exactly what was skipped.
20	 */
21	import { sha256 } from '../util/hash.js';
22	
23	export interface TrapGuardOptions {
24	  /** Pages of one template to observe before saturation may be declared. */
25	  sampleSize: number;
26	  /** Distinct shape hashes at or below which a template counts as repetitive. */
27	  maxDistinctShapes: number;
28	  /** Absolute cap on URLs enqueued per template, regardless of novelty. */
29	  maxPerTemplate: number;
30	}
31	
32	export const DEFAULT_TRAP_OPTIONS: TrapGuardOptions = {
33	  sampleSize: 25,
34	  maxDistinctShapes: 2,
35	  maxPerTemplate: 500,
36	};
37	
38	export interface TemplateStats {
39	  template: string;
40	  enqueued: number;
41	  fetched: number;
42	  distinctShapes: number;
43	  outboundNovelty: number;
44	  saturated: boolean;
45	  reason?: string;
46	  /** A representative URL, for the report. */
47	  example: string;
48	}
49	
50	export class TrapGuard {
51	  private readonly templates = new Map<string, TemplateStats>();
52	  private readonly shapes = new Map<string, Set<string>>();
53	  private readonly options: TrapGuardOptions;
54	
55	  constructor(options: Partial<TrapGuardOptions> = {}) {
56	    this.options = { ...DEFAULT_TRAP_OPTIONS, ...options };
57	  }
58	
59	  /** Called before enqueuing. Returns false when the URL's template is closed. */
60	  allow(url: string): boolean {
61	    const template = templateKey(url);
62	    const stats = this.statsFor(template, url);
63	    if (stats.saturated) return false;
64	    if (stats.enqueued >= this.options.maxPerTemplate) {
65	      stats.saturated = true;
66	      stats.reason =
67	        `hard cap: ${this.options.maxPerTemplate} URLs enqueued for this template ` +
68	        'without the novelty heuristic closing it';
69	      return false;
70	    }
71	    stats.enqueued += 1;
72	    return true;
73	  }
74	
75	  /**
76	   * Record what a fetched page of a template contained.
77	   *
78	   * @param outboundNovelty count of URLs this page contributed that fall outside
79	   *        its own template — the signal that the template is still a real crawl
80	   *        frontier rather than a self-referential loop.
81	   */
82	  observe(url: string, body: Buffer, outboundNovelty: number): void {
83	    const template = templateKey(url);
84	    const stats = this.statsFor(template, url);
85	    stats.fetched += 1;
86	    stats.outboundNovelty += outboundNovelty;
87	
88	    const set = this.shapes.get(template) ?? new Set<string>();
89	    set.add(shapeHash(body));
90	    this.shapes.set(template, set);
91	    stats.distinctShapes = set.size;
92	
93	    if (stats.saturated) return;
94	    if (stats.fetched < this.options.sampleSize) return;
95	    if (set.size > this.options.maxDistinctShapes) return;
96	    if (stats.outboundNovelty > 0) return;
97	
98	    stats.saturated = true;
99	    stats.reason =
100	      `${stats.fetched} pages sampled reduced to ${set.size} distinct page shape(s) ` +
101	      'and contributed no URLs outside the template';
102	  }
103	
104	  get report(): TemplateStats[] {
105	    return [...this.templates.values()].sort((a, b) => b.enqueued - a.enqueued);
106	  }
107	
108	  get saturated(): TemplateStats[] {
109	    return this.report.filter((stats) => stats.saturated);
110	  }
111	
112	  private statsFor(template: string, url: string): TemplateStats {
113	    let stats = this.templates.get(template);
114	    if (!stats) {
115	      stats = {
116	        template,
117	        enqueued: 0,
118	        fetched: 0,
119	        distinctShapes: 0,
120	        outboundNovelty: 0,
121	        saturated: false,
122	        example: url,
123	      };
124	      this.templates.set(template, stats);
125	    }
126	    return stats;
127	  }
128	}
129	
130	/**
131	 * Collapse a URL to its template: numeric-ish path segments and query values
132	 * become `{n}`, so `/report/?page=1` and `/report/?page=2424` share a key while
133	 * `/docs/upstream-sample-channel/` keeps its identity.
134	 */
135	export function templateKey(url: string): string {
136	  let parsed: URL;
137	  try {
138	    parsed = new URL(url);
139	  } catch {
140	    return url;
141	  }
142	  const path = parsed.pathname
143	    .split('/')
144	    .map((segment) => (/^\d+$/.test(segment) || /^p?\d+$/i.test(segment) ? '{n}' : segment))
145	    .join('/');
146	  const query = [...parsed.searchParams.entries()]
147	    .map(([key, value]) => `${key}=${/^\d+$/.test(value) ? '{n}' : value}`)
148	    .sort()
149	    .join('&');
150	  return query ? `${path}?${query}` : path;
151	}
152	
153	/**
154	 * Fingerprint a page's *structure* rather than its content.
155	 *
156	 * For markup this is the sequence of tag names with consecutive repeats collapsed,
157	 * which is what actually distinguishes "another page of the same table" from "a
158	 * different kind of page". Hashing the text instead does not work here: the target
159	 * column of the monitoring report varies by *words*, not digits, so every page of
160	 * a single paginated table would otherwise hash differently and the generator
161	 * would never be recognised as one.
162	 *
163	 * Non-markup bodies fall back to masked text (digits and long hex runs replaced),
164	 * which is the right signal for a generated JSON or CSV feed.
165	 */
166	export function shapeHash(body: Buffer): string {
167	  const text = body.toString('utf8');
168	  const tags = [...text.matchAll(/<([a-zA-Z][\w-]*)/g)].map((match) =>
169	    (match[1] ?? '').toLowerCase(),
170	  );
171	  if (tags.length >= 4) {
172	    const collapsed: string[] = [];
173	    for (const tag of tags) {
174	      if (collapsed[collapsed.length - 1] !== tag) collapsed.push(tag);
175	    }
176	    return sha256(`tags:${collapsed.join(' ')}`);
177	  }
178	  const masked = text
179	    .replace(/[0-9a-f]{6,}/gi, '#')
180	    .replace(/\d+/g, '#')
181	    .replace(/\s+/g, ' ')
182	    .trim();
183	  return sha256(`text:${masked}`);
184	}

