  for (const hit of hits) {
    const existing = best.get(hit.password);
    if (!existing || specificity(hit) > specificity(existing)) best.set(hit.password, hit);
  }
  return [...best.values()].sort((a, b) => a.password.localeCompare(b.password));
}

